# app.R — Menstrual Cycle & Fertility Insights
# ==================================================
library(shiny)
library(lubridate)
library(dplyr)
library(tidyr)
library(DT)
library(ggplot2)
library(plotly)
library(scales)
library(readr)

# ---------- Calm Cycle Palette ----------
phase_colors <- c(
  "Menstrual"  = "#C98A8A",   # dusty rose
  "Follicular" = "#9FBC9A",   # sage
  "Ovulation"  = "#E5B87C",   # soft amber
  "Luteal"     = "#B29AC4"    # muted lavender
)

# Soft-tint versions for card backgrounds (10-14% of phase color)
phase_tints <- c(
  "Menstrual"  = "#F7EDEC",
  "Follicular" = "#EEF3EC",
  "Ovulation"  = "#FAF1E3",
  "Luteal"     = "#F1EDF5"
)

sexdrive_colors <- c(
  "Low"    = "#E6DFD8",
  "Medium" = "#D4A88C",
  "High"   = "#B85C5C"
)
sexdrive_levels <- c("Low", "Medium", "High")

# Shared UI palette
ui_colors <- list(
  bg        = "#FBF7F3",
  surface   = "#FFFFFF",
  surface2  = "#F6F1EB",
  text      = "#3D3535",
  text_soft = "#80736E",
  accent    = "#C48A8A",
  accent2   = "#9FBC9A",
  border    = "#EDE5DD",
  shadow    = "0 4px 24px rgba(120, 90, 80, 0.06)",
  shadow_hi = "0 8px 32px rgba(120, 90, 80, 0.10)"
)

phase_info <- list(
  Menstrual = list(
    emoji = "\U0001FA78",
    energy = "Low to moderate",
    mood = "May feel tired, quiet, or emotionally variable",
    food = "Dal, leafy greens, eggs, khichdi, soups, nuts, vitamin C fruits. Iron-rich foods + hydration."
  ),
  Follicular = list(
    emoji = "\U0001F331",
    energy = "Often increases",
    mood = "More positive, motivated, focused",
    food = "Eggs, paneer, tofu, dal, curd, oats, fruits, vegetables, nuts, seeds. Protein-focused meals."
  ),
  Ovulation = list(
    emoji = "\U0001F33C",
    energy = "May be at its peak",
    mood = "Upbeat, confident, social; libido may increase",
    food = "Balanced meals with protein, vegetables, whole grains, nuts, seeds. Hydration + fruits."
  ),
  Luteal = list(
    emoji = "\U0001F319",
    energy = "May gradually decrease",
    mood = "Cravings, irritability, sensitivity, lower motivation (esp. near period)",
    food = "Oats, whole-wheat roti, rice, dal, beans, spinach, almonds, pumpkin seeds, curd, dark chocolate."
  )
)

# ---------- Helpers ----------
normalize_sexdrive <- function(x) {
  x <- tolower(trimws(as.character(x)))
  dplyr::case_when(
    x %in% c("2", "2.0", "high", "h")           ~ "High",
    x %in% c("1", "1.0", "medium", "med", "m")  ~ "Medium",
    x %in% c("0", "0.0", "low", "l")            ~ "Low",
    TRUE                                        ~ NA_character_
  )
}

generate_cycle_data <- function(lmp_date, cycle_length, period_length, months = 13) {
  start_date <- as.Date(lmp_date)
  end_date   <- start_date %m+% months(months)
  dates      <- seq.Date(start_date, end_date, by = "day")
  days_since <- as.numeric(dates - start_date)
  cycle_day  <- (days_since %% cycle_length) + 1
  
  ovulation_day <- max(cycle_length - 14, period_length + 1)
  
  phase <- dplyr::case_when(
    cycle_day <= period_length     ~ "Menstrual",
    cycle_day <  ovulation_day - 1 ~ "Follicular",
    cycle_day <= ovulation_day + 1 ~ "Ovulation",
    TRUE                           ~ "Luteal"
  )
  
  fertile_start <- ovulation_day - 4
  fertile_end   <- ovulation_day + 1
  fertile       <- cycle_day >= fertile_start & cycle_day <= fertile_end
  
  fert_prob <- exp(-0.5 * ((cycle_day - ovulation_day) / 2)^2)
  fert_prob[!fertile] <- fert_prob[!fertile] * 0.05
  
  auto_sex_drive <- dplyr::case_when(
    cycle_day <= period_length     ~ "Low",
    cycle_day <= ovulation_day - 5 ~ "Medium",
    cycle_day <= ovulation_day + 1 ~ "High",
    cycle_day <= ovulation_day + 6 ~ "Medium",
    TRUE                           ~ "Low"
  )
  
  energy <- dplyr::case_when(
    phase == "Menstrual"  ~ "Low",
    phase == "Follicular" ~ "Rising",
    phase == "Ovulation"  ~ "Peak",
    phase == "Luteal"     ~ "Declining"
  )
  
  out <- tibble(
    Date                 = dates,
    CycleDay             = cycle_day,
    Phase                = factor(phase, levels = names(phase_colors)),
    Fertile              = fertile,
    FertilityProbability = round(fert_prob, 3),
    AutoSexDrive         = auto_sex_drive,
    Energy               = energy
  )
  
  out$MonthYear <- factor(format(out$Date, "%b %Y"),
                          levels = unique(format(out$Date, "%b %Y")))
  out$WeekdayLabel <- factor(
    wday(out$Date, label = TRUE, abbr = TRUE, week_start = 1),
    levels = c("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")
  )
  out$DayOfMonth  <- day(out$Date)
  out$WeekOfMonth <- ((out$DayOfMonth +
                         wday(floor_date(out$Date, "month"), week_start = 1) - 2) %/% 7) + 1
  out
}

# ---------- UI ----------
ui <- fluidPage(
  tags$head(
    # Google Fonts (loads once, cached by service worker for offline use)
    tags$link(rel = "preconnect", href = "https://fonts.googleapis.com"),
    tags$link(rel = "preconnect", href = "https://fonts.gstatic.com", crossorigin = NA),
    tags$link(rel = "stylesheet",
              href = "https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600&family=Inter:wght@400;500;600&display=swap"),
    
    tags$style(HTML("
      /* ==================================================================
         CALM CYCLE — immersive, fluid, gentle
         ================================================================== */

      :root {
        --bg:         #FBF7F3;
        --surface:    #FFFFFF;
        --surface-2:  #F6F1EB;
        --text:       #3D3535;
        --text-soft:  #80736E;
        --accent:     #C48A8A;
        --accent-2:   #9FBC9A;
        --border:     #EDE5DD;
        --shadow:     0 4px 24px rgba(120, 90, 80, 0.06);
        --shadow-hi:  0 8px 32px rgba(120, 90, 80, 0.10);
        --radius:     16px;
        --radius-sm:  10px;
        --ease:       cubic-bezier(0.4, 0, 0.2, 1);
      }

      /* ---------- Base layout ---------- */
      html, body {
        height: 100% !important;
        margin: 0 !important;
        padding: 0 !important;
        overflow: hidden;
        font-family: 'Inter', system-ui, -apple-system, 'Segoe UI', sans-serif !important;
        color: var(--text);
        background: var(--bg);
        -webkit-font-smoothing: antialiased;
      }

      /* Ambient radial glow — subtle, alive */
      body::before {
        content: '';
        position: fixed;
        top: -20%;
        left: -10%;
        width: 60%;
        height: 60%;
        background: radial-gradient(circle, rgba(201,138,138,0.08) 0%, transparent 70%);
        pointer-events: none;
        z-index: 0;
        animation: ambientDrift 24s ease-in-out infinite alternate;
      }
      body::after {
        content: '';
        position: fixed;
        bottom: -20%;
        right: -10%;
        width: 55%;
        height: 55%;
        background: radial-gradient(circle, rgba(159,188,154,0.07) 0%, transparent 70%);
        pointer-events: none;
        z-index: 0;
        animation: ambientDrift 30s ease-in-out infinite alternate-reverse;
      }
      @keyframes ambientDrift {
        0%   { transform: translate(0, 0)    scale(1);    }
        100% { transform: translate(4%, 3%)  scale(1.15); }
      }

      /* ---------- Container: flex column, full height ---------- */
      .container-fluid {
        position: relative;
        z-index: 1;
        height: 100vh !important;
        display: flex !important;
        flex-direction: column !important;
        padding: 20px 28px !important;
        max-width: 1600px;
        margin: 0 auto;
      }
      .container-fluid > .row {
        flex: 1 1 auto !important;
        min-height: 0 !important;
        display: flex !important;
      }
      .container-fluid > .row > [class*='col-'] {
        height: 100%;
        overflow-y: auto;
        overflow-x: hidden;
        padding-right: 14px;
      }
      /* Gentle scrollbar */
      .container-fluid > .row > [class*='col-']::-webkit-scrollbar { width: 6px; }
      .container-fluid > .row > [class*='col-']::-webkit-scrollbar-thumb {
        background: rgba(201,138,138,0.25);
        border-radius: 3px;
      }
      .container-fluid > .row > [class*='col-']::-webkit-scrollbar-track { background: transparent; }

      /* ---------- Title ---------- */
      .container-fluid h2 {
        font-family: 'Fraunces', Georgia, serif !important;
        font-weight: 500 !important;
        font-size: 30px !important;
        letter-spacing: -0.02em;
        color: var(--text);
        margin: 0 0 24px 0 !important;
        padding: 0 !important;
        border: none !important;
        display: flex;
        align-items: center;
        gap: 12px;
      }
      .container-fluid h2::before {
        content: '';
        display: inline-block;
        width: 36px;
        height: 36px;
        background: radial-gradient(circle at 40% 40%,
                    #E7BFC0 0%, #C98A8A 60%, #A96666 100%);
        border-radius: 50%;
        box-shadow: 0 4px 12px rgba(201,138,138,0.25);
        flex-shrink: 0;
      }

      /* Hide Shiny's default title text since we style h2 above */
      .container-fluid > h2:first-child { padding-top: 0; }

      /* ---------- Sidebar (inputs) ---------- */
      .well {
        background: var(--surface) !important;
        border: 1px solid var(--border) !important;
        border-radius: var(--radius) !important;
        box-shadow: var(--shadow) !important;
        padding: 22px !important;
        transition: box-shadow 0.25s var(--ease);
      }
      .well:hover {
        box-shadow: var(--shadow-hi) !important;
      }

      .form-group label, .control-label {
        font-weight: 500 !important;
        font-size: 13px !important;
        color: var(--text-soft) !important;
        text-transform: uppercase;
        letter-spacing: 0.06em;
        margin-bottom: 8px !important;
      }

      .form-control, select.form-control {
        background: var(--surface-2) !important;
        border: 1px solid transparent !important;
        border-radius: var(--radius-sm) !important;
        padding: 10px 14px !important;
        font-size: 14px !important;
        color: var(--text) !important;
        transition: all 0.2s var(--ease);
        height: auto !important;
      }
      .form-control:focus {
        background: var(--surface) !important;
        border-color: var(--accent) !important;
        box-shadow: 0 0 0 4px rgba(196,138,138,0.12) !important;
        outline: none;
      }

      /* Sliders / checkboxes */
      input[type='checkbox'] { accent-color: var(--accent); transform: scale(1.05); }
      .checkbox label { text-transform: none; letter-spacing: 0; font-size: 14px !important; color: var(--text) !important; }

      /* Buttons */
      .btn {
        border-radius: var(--radius-sm) !important;
        padding: 10px 18px !important;
        font-size: 14px !important;
        font-weight: 500 !important;
        border: none !important;
        transition: all 0.2s var(--ease);
        letter-spacing: 0.01em;
      }
      .btn-primary {
        background: linear-gradient(135deg, #D4A0A0 0%, #C48A8A 100%) !important;
        color: white !important;
        box-shadow: 0 4px 12px rgba(196,138,138,0.20) !important;
      }
      .btn-primary:hover, .btn-primary:focus {
        transform: translateY(-1px);
        box-shadow: 0 6px 18px rgba(196,138,138,0.28) !important;
      }
      .btn-default {
        background: var(--surface-2) !important;
        color: var(--text) !important;
      }
      .btn-default:hover { background: var(--border) !important; }

      /* HR */
      hr {
        border: none;
        border-top: 1px solid var(--border);
        margin: 20px 0;
      }

      /* Help text */
      .help-block, .shiny-text-output {
        color: var(--text-soft) !important;
        font-size: 12.5px !important;
        line-height: 1.6;
      }

      /* ---------- Tabs ---------- */
      .nav-tabs {
        border-bottom: none !important;
        gap: 6px;
        margin-bottom: 18px;
        background: transparent;
      }
      .nav-tabs > li {
        margin: 0 !important;
      }
      .nav-tabs > li > a {
        border: none !important;
        border-radius: var(--radius-sm) !important;
        padding: 10px 18px !important;
        color: var(--text-soft) !important;
        font-weight: 500 !important;
        font-size: 13.5px !important;
        background: transparent !important;
        transition: all 0.2s var(--ease);
        margin: 0 !important;
      }
      .nav-tabs > li > a:hover {
        background: var(--surface-2) !important;
        color: var(--text) !important;
      }
      .nav-tabs > li.active > a,
      .nav-tabs > li.active > a:focus {
        background: var(--surface) !important;
        color: var(--text) !important;
        box-shadow: 0 2px 8px rgba(120,90,80,0.08) !important;
        border: 1px solid var(--border) !important;
      }

      /* Tab pane fade-in */
      .tab-pane {
        animation: fadeIn 0.35s var(--ease);
      }
      @keyframes fadeIn {
        from { opacity: 0; transform: translateY(4px); }
        to   { opacity: 1; transform: translateY(0);   }
      }

      /* ---------- Tab content area ---------- */
      .tabbable, .tab-content { height: 100%; }
      .tab-content {
        overflow-y: auto;
        padding-top: 4px;
      }
      .tab-content::-webkit-scrollbar { width: 6px; }
      .tab-content::-webkit-scrollbar-thumb {
        background: rgba(201,138,138,0.20);
        border-radius: 3px;
      }

      /* ---------- Phase cards ---------- */
      .phase-card {
        background: var(--surface);
        border-radius: var(--radius);
        padding: 22px 24px;
        margin-bottom: 14px;
        box-shadow: var(--shadow);
        border-left: 4px solid transparent;
        transition: all 0.25s var(--ease);
      }
      .phase-card:hover {
        transform: translateY(-2px);
        box-shadow: var(--shadow-hi);
      }
      .phase-card h4 {
        font-family: 'Fraunces', Georgia, serif !important;
        font-weight: 500 !important;
        font-size: 18px !important;
        margin: 0 0 12px 0 !important;
        color: var(--text) !important;
      }
      .phase-card p {
        margin: 6px 0 !important;
        color: var(--text-soft);
        font-size: 13.5px;
        line-height: 1.55;
      }
      .phase-card p strong { color: var(--text); font-weight: 500; }

      .phase-card.phase-Menstrual  { border-left-color: #C98A8A; background: linear-gradient(135deg, #FDF9F8 0%, #F7EDEC 100%); }
      .phase-card.phase-Follicular { border-left-color: #9FBC9A; background: linear-gradient(135deg, #FAFCF9 0%, #EEF3EC 100%); }
      .phase-card.phase-Ovulation  { border-left-color: #E5B87C; background: linear-gradient(135deg, #FEFBF6 0%, #FAF1E3 100%); }
      .phase-card.phase-Luteal     { border-left-color: #B29AC4; background: linear-gradient(135deg, #FBF9FC 0%, #F1EDF5 100%); }

      /* ---------- Stat boxes ---------- */
      .stat-box {
        background: var(--surface);
        border: 1px solid var(--border);
        border-radius: var(--radius);
        padding: 20px 18px;
        margin: 8px 0;
        text-align: center;
        transition: all 0.25s var(--ease);
      }
      .stat-box:hover {
        transform: translateY(-2px);
        box-shadow: var(--shadow);
        border-color: var(--accent);
      }
      .stat-val {
        font-family: 'Fraunces', Georgia, serif !important;
        font-size: 26px !important;
        font-weight: 500 !important;
        color: var(--text) !important;
        letter-spacing: -0.01em;
        margin-bottom: 4px;
      }
      .stat-lbl {
        font-size: 11px !important;
        color: var(--text-soft) !important;
        text-transform: uppercase;
        letter-spacing: 0.08em;
        font-weight: 500;
      }

      /* ---------- Drive pills ---------- */
      .drive-pill {
        display: inline-block;
        padding: 8px 18px;
        margin: 4px 5px;
        border-radius: 999px;
        color: white;
        font-weight: 500;
        font-size: 13px;
        letter-spacing: 0.02em;
        box-shadow: 0 2px 8px rgba(120,90,80,0.10);
        transition: transform 0.2s var(--ease);
      }
      .drive-pill:hover { transform: translateY(-1px); }
      .drive-legend {
        margin-left: 14px;
        color: var(--text-soft);
        font-size: 12.5px;
        letter-spacing: 0.02em;
      }

      /* ---------- Alerts ---------- */
      .alert {
        border: none !important;
        border-radius: var(--radius) !important;
        padding: 18px 22px !important;
        font-size: 13.5px !important;
        line-height: 1.6;
        background: linear-gradient(135deg, #FBF6EE 0%, #F5EBDC 100%) !important;
        color: var(--text) !important;
      }
      .alert-warning { border-left: 4px solid #E5B87C !important; }

      /* ---------- DataTables ---------- */
      .dataTables_wrapper { font-size: 13px !important; }
      table.dataTable {
        border-collapse: separate !important;
        border-spacing: 0 !important;
        border-radius: var(--radius-sm);
        overflow: hidden;
      }
      table.dataTable thead th {
        background: var(--surface-2) !important;
        border: none !important;
        color: var(--text-soft) !important;
        font-weight: 500 !important;
        font-size: 12px !important;
        text-transform: uppercase;
        letter-spacing: 0.05em;
        padding: 12px 14px !important;
      }
      table.dataTable tbody td {
        border-top: 1px solid var(--border) !important;
        padding: 10px 14px !important;
        color: var(--text) !important;
      }
      table.dataTable tbody tr:hover {
        background: var(--surface-2) !important;
        transition: background 0.15s var(--ease);
      }

      /* Pagination */
      .dataTables_paginate a.paginate_button {
        border-radius: var(--radius-sm) !important;
        padding: 6px 12px !important;
        border: none !important;
        background: var(--surface-2) !important;
        color: var(--text) !important;
        margin: 0 3px !important;
        transition: all 0.15s var(--ease);
      }
      .dataTables_paginate a.paginate_button:hover {
        background: var(--accent) !important;
        color: white !important;
      }
      .dataTables_paginate a.paginate_button.current {
        background: var(--accent) !important;
        color: white !important;
      }

      /* ---------- Plotly overrides ---------- */
      .plotly .main-svg { background: transparent !important; }
      .plotly .gridlayer path { stroke: #F0E8E0 !important; }
      .plotly .xtick text, .plotly .ytick text {
        font-family: 'Inter', sans-serif !important;
        font-size: 11.5px !important;
        fill: var(--text-soft) !important;
      }
      .plotly .gtitle {
        font-family: 'Fraunces', Georgia, serif !important;
        font-size: 17px !important;
        fill: var(--text) !important;
        font-weight: 500 !important;
      }
      .plotly .legendtext {
        font-family: 'Inter', sans-serif !important;
        font-size: 11.5px !important;
        fill: var(--text) !important;
      }

      /* ---------- Today pulse ---------- */
      @keyframes todayPulse {
        0%, 100% { opacity: 1;   transform: scale(1);    }
        50%      { opacity: 0.7; transform: scale(1.08); }
      }
      .today-marker { animation: todayPulse 3s ease-in-out infinite; }

      /* ---------- General smooth entry ---------- */
      .shiny-plot-output, .shiny-html-output {
        animation: fadeIn 0.4s var(--ease);
      }
    "))
  ),
  
  titlePanel("\U0001F338 Menstrual Cycle & Fertility Insights"),
  
  sidebarLayout(
    sidebarPanel(
      width = 3,
      dateInput("lmp", "Last menstrual period (LMP):",
                value = as.Date("2026-09-25")),
      numericInput("cycle_len",  "Cycle length (days):",
                   value = 28, min = 21, max = 40, step = 1),
      numericInput("period_len", "Period length (days):",
                   value = 5,  min = 2,  max = 10, step = 1),
      hr(),
      fileInput("csv_upload", "Upload CSV (Date, SexDrive) [optional]",
                accept = c(".csv", "text/csv")),
      helpText("Date format: DD-MM-YYYY. SexDrive: Low / Medium / High. ",
               "Uploaded values override the auto-generated sex drive."),
      hr(),
      selectInput("view_mode", "Annual calendar shows:",
                  choices = c("Phase", "Sex Drive",
                              "Fertility Probability", "Cycle Day"),
                  selected = "Sex Drive"),
      checkboxInput("show_fertile_border",
                    "Highlight fertile window", value = TRUE),
      checkboxInput("show_labels", "Show day numbers", value = TRUE),
      hr(),
      selectInput("month_select", "Jump to month:", choices = NULL),
      hr(),
      downloadButton("download_csv", "Download CSV", class = "btn-primary"),
      br(), br(),
      helpText("All predictions are estimates. Do not rely on calendar",
               "methods alone for contraception.")
    ),
    
    mainPanel(
      width = 9,
      tabsetPanel(
        tabPanel("\U0001F4C5 Annual Calendar",
                 br(),
                 uiOutput("annual_drive_summary"),
                 plotlyOutput("annual_cal", height = "720px")),
        tabPanel("\U0001F50D Monthly View",
                 br(),
                 fluidRow(
                   column(6, plotOutput("monthly_cal",    height = "450px")),
                   column(6, plotlyOutput("monthly_fert", height = "450px"))
                 ),
                 br(),
                 uiOutput("month_cards")),
        tabPanel("\U0001F4C8 Fertility Curve",
                 br(),
                 plotlyOutput("fert_curve", height = "520px")),
        tabPanel("\U0001F4A1 Insights",
                 br(),
                 uiOutput("insights_ui")),
        tabPanel("\U0001F4CB Data Table",
                 br(),
                 DTOutput("data_tbl"))
      )
    )
  )
)

# ---------- Server ----------
server <- function(input, output, session) {
  
  uploaded <- reactive({
    if (is.null(input$csv_upload)) return(NULL)
    df <- tryCatch(
      readr::read_csv(input$csv_upload$datapath, show_col_types = FALSE),
      error = function(e) NULL
    )
    if (is.null(df) || nrow(df) == 0) return(NULL)
    
    names(df) <- tolower(trimws(names(df)))
    date_col <- grep("^date$", names(df), value = TRUE)[1]
    sd_col   <- grep("^sex.?drive$|^sexdrive$|^drive$", names(df), value = TRUE)[1]
    if (is.na(date_col) || is.na(sd_col)) return(NULL)
    
    out <- tibble(
      Date         = suppressWarnings(
        parse_date_time(as.character(df[[date_col]]),
                        orders = c("dmy", "ymd", "mdy"))
      ),
      UserSexDrive = normalize_sexdrive(df[[sd_col]])
    )
    out %>% filter(!is.na(Date), !is.na(UserSexDrive))
  })
  
  cycle_df <- reactive({
    req(input$lmp, input$cycle_len, input$period_len)
    validate(need(input$cycle_len >= input$period_len + 5,
                  "Cycle length must exceed period length by at least 5 days."))
    
    df <- generate_cycle_data(input$lmp, input$cycle_len,
                              input$period_len, months = 13)
    
    up <- uploaded()
    if (!is.null(up) && nrow(up) > 0) {
      up <- up %>% group_by(Date) %>% slice(dplyr::n()) %>% ungroup()
      df <- df %>%
        left_join(up, by = "Date") %>%
