# app.R  —  Menstrual Cycle & Fertility Insights (final, clean)
# =================================================================
library(shiny)
library(lubridate)
library(dplyr)
library(tidyr)
library(DT)
library(ggplot2)
library(plotly)
library(scales)
library(readr)

# ----------------- Constants -----------------
phase_colors <- c(
  "Menstrual"  = "#e56b6f",
  "Follicular" = "#74c69d",
  "Ovulation"  = "#f9c74f",
  "Luteal"     = "#9d4edd"
)

sexdrive_colors <- c(
  "Low"    = "#d3d3d3",
  "Medium" = "#f4a261",
  "High"   = "#d62828"
)
sexdrive_levels <- c("Low", "Medium", "High")

phase_info <- list(
  Menstrual = list(
    emoji = "\U0001FA78",
    energy = "Low to moderate",
    mood = "May feel tired, quiet, or emotionally variable",
    food = "Dal, leafy greens, eggs, khichdi, soups, nuts, vitamin C fruits. Iron-rich foods + hydration."
  ),
  Follicular = list(
    emoji = "\U0001F331",
    energy = "Often increases",
    mood = "More positive, motivated, focused",
    food = "Eggs, paneer, tofu, dal, curd, oats, fruits, vegetables, nuts, seeds. Protein-focused meals."
  ),
  Ovulation = list(
    emoji = "\U0001F33C",
    energy = "May be at its peak",
    mood = "Upbeat, confident, social; libido may increase",
    food = "Balanced meals with protein, vegetables, whole grains, nuts, seeds. Hydration + fruits."
  ),
  Luteal = list(
    emoji = "\U0001F319",
    energy = "May gradually decrease",
    mood = "Cravings, irritability, sensitivity, lower motivation (esp. near period)",
    food = "Oats, whole-wheat roti, rice, dal, beans, spinach, almonds, pumpkin seeds, curd, dark chocolate."
  )
)

# ----------------- Helpers -----------------
normalize_sexdrive <- function(x) {
  x <- tolower(trimws(as.character(x)))
  dplyr::case_when(
    x %in% c("2", "2.0", "high", "h")           ~ "High",
    x %in% c("1", "1.0", "medium", "med", "m")  ~ "Medium",
    x %in% c("0", "0.0", "low", "l")            ~ "Low",
    TRUE                                        ~ NA_character_
  )
}

generate_cycle_data <- function(lmp_date, cycle_length, period_length, months = 13) {
  start_date <- as.Date(lmp_date)
  end_date   <- start_date %m+% months(months)
  dates      <- seq.Date(start_date, end_date, by = "day")
  days_since <- as.numeric(dates - start_date)
  cycle_day  <- (days_since %% cycle_length) + 1
  
  ovulation_day <- max(cycle_length - 14, period_length + 1)
  
  phase <- dplyr::case_when(
    cycle_day <= period_length     ~ "Menstrual",
    cycle_day <  ovulation_day - 1 ~ "Follicular",
    cycle_day <= ovulation_day + 1 ~ "Ovulation",
    TRUE                           ~ "Luteal"
  )
  
  fertile_start <- ovulation_day - 4
  fertile_end   <- ovulation_day + 1
  fertile       <- cycle_day >= fertile_start & cycle_day <= fertile_end
  
  fert_prob <- exp(-0.5 * ((cycle_day - ovulation_day) / 2)^2)
  fert_prob[!fertile] <- fert_prob[!fertile] * 0.05
  
  auto_sex_drive <- dplyr::case_when(
    cycle_day <= period_length     ~ "Low",
    cycle_day <= ovulation_day - 5 ~ "Medium",
    cycle_day <= ovulation_day + 1 ~ "High",
    cycle_day <= ovulation_day + 6 ~ "Medium",
    TRUE                           ~ "Low"
  )
  
  energy <- dplyr::case_when(
    phase == "Menstrual"  ~ "Low",
    phase == "Follicular" ~ "Rising",
    phase == "Ovulation"  ~ "Peak",
    phase == "Luteal"     ~ "Declining"
  )
  
  out <- tibble(
    Date                 = dates,
    CycleDay             = cycle_day,
    Phase                = factor(phase, levels = names(phase_colors)),
    Fertile              = fertile,
    FertilityProbability = round(fert_prob, 3),
    AutoSexDrive         = auto_sex_drive,
    Energy               = energy
  )
  
  out$MonthYear <- factor(format(out$Date, "%b %Y"),
                          levels = unique(format(out$Date, "%b %Y")))
  out$WeekdayLabel <- factor(
    wday(out$Date, label = TRUE, abbr = TRUE, week_start = 1),
    levels = c("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")
  )
  out$DayOfMonth  <- day(out$Date)
  out$WeekOfMonth <- ((out$DayOfMonth +
                         wday(floor_date(out$Date, "month"), week_start = 1) - 2) %/% 7) + 1
  
  out
}

