      padding-top: 8px;
    }

    /* ---------- Keep your existing decorative styles ---------- */
    .phase-card {
      padding: 14px 18px;
      border-radius: 10px;
      color: white;
      margin-bottom: 10px;
    }
    .phase-Menstrual  { background: #e56b6f; }
    .phase-Follicular { background: #74c69d; }
    .phase-Ovulation  { background: #f9c74f; color: #333; }
    .phase-Luteal     { background: #9d4edd; }

    .stat-box {
      background: #f8f9fa;
      padding: 14px;
      border-radius: 8px;
      margin: 6px 0;
      text-align: center;
      border: 1px solid #e9ecef;
    }
    .stat-val {
      font-size: 22px;
      font-weight: 700;
      color: #4361ee;
    }
    .stat-lbl {
      font-size: 11px;
      color: #6c757d;
      text-transform: uppercase;
      letter-spacing: 0.6px;
    }

    .drive-pill {
      display: inline-block;
      padding: 8px 16px;
      margin-right: 10px;
      border-radius: 20px;
      color: white;
      font-weight: 600;
    }
    .drive-legend {
      margin-left: 12px;
      color: #666;
      font-size: 13px;
    }
  "))),
  
  titlePanel("\U0001F338 Menstrual Cycle & Fertility Insights"),
  
  sidebarLayout(
    sidebarPanel(
      width = 3,
      dateInput("lmp", "Last menstrual period (LMP):",
                value = as.Date("2026-09-25")),
      numericInput("cycle_len",  "Cycle length (days):",
                   value = 28, min = 21, max = 40, step = 1),
      numericInput("period_len", "Period length (days):",
                   value = 5,  min = 2,  max = 10, step = 1),
      hr(),
      fileInput("csv_upload", "Upload CSV (Date, SexDrive) [optional]",
                accept = c(".csv", "text/csv")),
      helpText("Date format: DD-MM-YYYY. SexDrive: Low / Medium / High. ",
               "Uploaded values override the auto-generated sex drive."),
      hr(),
      selectInput("view_mode", "Annual calendar shows:",
                  choices = c("Phase", "Sex Drive",
                              "Fertility Probability", "Cycle Day"),
                  selected = "Sex Drive"),
      checkboxInput("show_fertile_border",
                    "Highlight fertile window", value = TRUE),
      checkboxInput("show_labels", "Show day numbers", value = TRUE),
      hr(),
      selectInput("month_select", "Jump to month:", choices = NULL),
      hr(),
      downloadButton("download_csv", "Download CSV", class = "btn-primary"),
      br(), br(),
      helpText("All predictions are estimates. Do not rely on calendar",
               "methods alone for contraception.")
    ),
    
    mainPanel(
      width = 9,
      tabsetPanel(
        tabPanel("\U0001F4C5 Annual Calendar",
                 br(),
                 uiOutput("annual_drive_summary"),
                 plotlyOutput("annual_cal", height = "720px")),
        tabPanel("\U0001F50D Monthly View",
                 br(),
                 fluidRow(
                   column(6, plotOutput("monthly_cal",    height = "450px")),
                   column(6, plotlyOutput("monthly_fert", height = "450px"))
                 ),
                 br(),
                 uiOutput("month_cards")),
        tabPanel("\U0001F4C8 Fertility Curve",
                 br(),
                 plotlyOutput("fert_curve", height = "520px")),
        tabPanel("\U0001F4A1 Insights",
                 br(),
                 uiOutput("insights_ui")),
        tabPanel("\U0001F4CB Data Table",
                 br(),
                 DTOutput("data_tbl"))
      )
    )
  )
)

# ----------------- Server -----------------
server <- function(input, output, session) {
  
  # Compact "1-3, 10-14, 28-31" for a vector of day numbers
  format_days <- function(days) {
    days <- sort(unique(as.integer(days)))
    if (length(days) == 0) return("---")
    groups <- cumsum(c(1, diff(days) != 1))
    parts  <- tapply(days, groups, function(g) {
      if (length(g) == 1) as.character(g)
      else if (length(g) == 2) paste(g, collapse = ", ")
      else paste0(min(g), "-", max(g))
    })
    paste(parts, collapse = ", ")
  }
  
  # ---- CSV upload (reactive) ----
  uploaded <- reactive({
    if (is.null(input$csv_upload)) return(NULL)
    
    df <- tryCatch(
      readr::read_csv(input$csv_upload$datapath, show_col_types = FALSE),
      error = function(e) NULL
    )
    if (is.null(df) || nrow(df) == 0) return(NULL)
    
    names(df) <- tolower(trimws(names(df)))
    date_col <- grep("^date$", names(df), value = TRUE)[1]
    sd_col   <- grep("^sex.?drive$|^sexdrive$|^drive$", names(df), value = TRUE)[1]
    if (is.na(date_col) || is.na(sd_col)) return(NULL)
    
    out <- tibble(
      Date         = suppressWarnings(
        parse_date_time(as.character(df[[date_col]]),
                        orders = c("dmy", "ymd", "mdy"))
      ),
      UserSexDrive = normalize_sexdrive(df[[sd_col]])
    )
    out <- out %>% filter(!is.na(Date), !is.na(UserSexDrive))
    out
  })
  
  # ---- Auto calendar + user overrides ----
  cycle_df <- reactive({
    req(input$lmp, input$cycle_len, input$period_len)
    validate(need(input$cycle_len >= input$period_len + 5,
                  "Cycle length must exceed period length by at least 5 days."))
    
    df <- generate_cycle_data(input$lmp, input$cycle_len,
                              input$period_len, months = 13)
    
    up <- uploaded()
    if (!is.null(up) && nrow(up) > 0) {
      up <- up %>% group_by(Date) %>% slice(dplyr::n()) %>% ungroup()
      df <- df %>%
        left_join(up, by = "Date") %>%
        mutate(
          SexDriveSource = ifelse(!is.na(UserSexDrive), "Uploaded", "Auto"),
          SexDrive       = factor(ifelse(!is.na(UserSexDrive),
                                         UserSexDrive, AutoSexDrive),
                                  levels = sexdrive_levels)
        ) %>%
        select(-UserSexDrive)
    } else {
      df <- df %>%
        mutate(SexDriveSource = "Auto",
               SexDrive       = factor(AutoSexDrive, levels = sexdrive_levels))
    }
    
    df$Tooltip <- paste0(
      format(df$Date, "%a, %d %b %Y"),
      "\nCycle Day: ", df$CycleDay,
      "\nPhase: ",     df$Phase,
      "\nSex Drive: ", df$SexDrive,
      " (", df$SexDriveSource, ")",
      "\nFertility: ", round(df$FertilityProbability * 100), "%",
      ifelse(df$Fertile, "\n(fertile window)", "")
    )
    
    df
  })
  
  # ---- Preserve month choice across input changes ----
  observe({
    months  <- levels(cycle_df()$MonthYear)
    current <- isolate(input$month_select)
    sel <- if (!is.null(current) && current %in% months) current else months[1]
    updateSelectInput(session, "month_select",
                      choices = months, selected = sel)
  })
  
  # ===== Sex-drive summary pills (only when that view is active) =====
  output$annual_drive_summary <- renderUI({
    req(input$view_mode == "Sex Drive")
    df <- cycle_df()
    tallies <- df %>% count(SexDrive, .drop = FALSE)
    
    get_n <- function(lvl) {
      v <- tallies$n[tallies$SexDrive == lvl]
      if (length(v) == 0) 0 else v
    }
    
    pill <- function(color, label, n) {
      div(class = "drive-pill", style = paste0("background:", color, ";"),
          paste0(label, ": ", n, " days"))
    }
    
    div(style = "text-align:center; margin-bottom:10px;",
        pill("#d3d3d3", "Low",    get_n("Low")),
        pill("#f4a261", "Medium", get_n("Medium")),
        pill("#d62828", "High",   get_n("High")),
        span(class = "drive-legend",
             "\u2605 = High day   \u25CF = Medium day"))
  })
  
  # ===== Annual calendar =====
  output$annual_cal <- renderPlotly({
    df   <- cycle_df()
    view <- input$view_mode
    
    p <- ggplot(df, aes(x = WeekdayLabel, y = -WeekOfMonth, text = Tooltip))
    
    if (view == "Phase") {
      p <- p +
        geom_tile(aes(fill = Phase), color = "white", linewidth = 0.5) +
        scale_fill_manual(values = phase_colors, drop = FALSE)
    } else if (view == "Sex Drive") {
      p <- p +
        geom_tile(aes(fill = SexDrive), color = "white", linewidth = 0.5) +
        scale_fill_manual(values = sexdrive_colors, drop = FALSE) +
        geom_text(
          data = df %>% filter(SexDrive %in% c("Medium", "High")),
          aes(label = ifelse(SexDrive == "High", "\u2605", "\u25CF")),
          size = 3.2, color = "white", fontface = "bold"
        )
    } else if (view == "Fertility Probability") {
      p <- p +
        geom_tile(aes(fill = FertilityProbability),
                  color = "white", linewidth = 0.5) +
        scale_fill_gradient(low = "#e0fbfc", high = "#3d5a80",
                            limits = c(0, 1))
    } else {
      p <- p +
        geom_tile(aes(fill = CycleDay), color = "white", linewidth = 0.5) +
        scale_fill_gradient(low = "#ffd6e0", high = "#800f2f")
    }
    
    if (isTRUE(input$show_fertile_border)) {
      p <- p + geom_tile(data = df %>% filter(Fertile),
                         fill = NA, color = "#d62828", linewidth = 1.3)
    }
    
    if (isTRUE(input$show_labels)) {
      if (view == "Sex Drive") {
        p <- p + geom_text(aes(label = DayOfMonth), size = 2.0,
                           color = "#222", vjust = 1.6)
      } else {
        p <- p + geom_text(aes(label = DayOfMonth), size = 2.3,
                           color = "#222")
      }
    }
    
    p <- p +
      guides(fill = guide_legend(
        title = if (view == "Sex Drive") "Sex drive" else view,
        override.aes = list(color = NA)
      )) +
      facet_wrap(~ MonthYear, ncol = 4) +
      scale_x_discrete(position = "top") +
      scale_y_continuous(breaks = NULL) +
      labs(x = NULL, y = NULL, fill = view) +
      theme_minimal(base_size = 10) +
      theme(
        panel.grid      = element_blank(),
        axis.text.y     = element_blank(),
        axis.ticks      = element_blank(),
        strip.text      = element_text(face = "bold", size = 11, color = "#333"),
        legend.position = "bottom",
        panel.spacing   = unit(0.25, "lines"),
        plot.margin     = margin(5, 5, 5, 5)
      )
    
    ggplotly(p, tooltip = "text") %>%
      layout(margin = list(l = 20, r = 20, t = 20, b = 20),
             legend = list(orientation = "h", y = -0.05))
  })
  
  # ===== Monthly view =====
  monthly_df <- reactive({
    req(input$month_select)
    cycle_df() %>% filter(MonthYear == input$month_select)
  })
  
  output$monthly_cal <- renderPlot({
    df <- monthly_df()
    req(nrow(df) > 0)
    
    ggplot(df, aes(x = WeekdayLabel, y = -WeekOfMonth)) +
      geom_tile(aes(fill = Phase), color = "white", linewidth = 0.9) +
      scale_fill_manual(values = phase_colors, drop = FALSE) +
      geom_text(aes(label = DayOfMonth), size = 4.2,
                fontface = "bold", color = "#222", vjust = 0.7) +
      # High  → large star, top-right corner of the tile
      geom_point(data = df %>% filter(SexDrive == "High"),
                 aes(x = WeekdayLabel, y = -WeekOfMonth),
                 shape = 8, size = 3.0, color = "white", stroke = 1.1,
                 position = position_nudge(x = 0.28, y = 0.28)) +
      # Medium → small dot, bottom-left corner of the tile
      geom_point(data = df %>% filter(SexDrive == "Medium"),
                 aes(x = WeekdayLabel, y = -WeekOfMonth),
                 shape = 16, size = 1.8, color = "white",
                 position = position_nudge(x = -0.30, y = -0.30)) +
      scale_x_discrete(position = "top") +
      scale_y_continuous(breaks = NULL) +
      labs(x = NULL, y = NULL, fill = "Phase", title = input$month_select) +
      theme_minimal(base_size = 13) +
      theme(
        panel.grid      = element_blank(),
        axis.text.y     = element_blank(),
        axis.ticks      = element_blank(),
        plot.title      = element_text(face = "bold", size = 16, hjust = 0.5),
        legend.position = "bottom"
      )
  })
  
  output$monthly_fert <- renderPlotly({
    df <- monthly_df()
    req(nrow(df) > 0)
    
    p <- ggplot(df, aes(x = Date, y = FertilityProbability,
                        text = Tooltip, group = 1)) +
      geom_area(fill = "#ffd6e8", alpha = 0.7) +
      geom_line(color = "#d6336c", linewidth = 1.1) +
      geom_point(data = df %>% filter(Fertile),
                 color = "#d62828", size = 2.4) +
      scale_y_continuous(labels = percent_format(accuracy = 1),
                         limits = c(0, 1)) +
      labs(x = NULL, y = "Relative fertility probability",
           title = paste("Fertility curve -", input$month_select)) +
      theme_minimal(base_size = 12) +
      theme(plot.title = element_text(face = "bold", hjust = 0.5))
    
    ggplotly(p, tooltip = "text")
  })
  
  # ===== Month insight cards =====
  output$month_cards <- renderUI({
    df <- monthly_df()
    req(nrow(df) > 0)
    
    phases_present <- unique(as.character(df$Phase))
    fertile_days   <- df %>% filter(Fertile)
    high_drive     <- df %>% filter(SexDrive == "High")
    medium_drive   <- df %>% filter(SexDrive == "Medium")
    period_days    <- df %>% filter(Phase == "Menstrual")
    
    fmt_range <- function(v) format_days(v)
    
    stat_box <- function(val, lbl) {
      div(class = "stat-box",
          div(class = "stat-val", val),
          div(class = "stat-lbl", lbl))
    }
    
    make_card <- function(ph) {
      info <- phase_info[[ph]]
      days <- df %>% filter(Phase == ph) %>% pull(DayOfMonth)
      div(class = paste0("phase-card phase-", ph),
          h4(paste0(info$emoji, " ", ph, " phase")),
          p(strong("Days in month: "), paste(range(days), collapse = "-")),
          p(strong("Energy: "), info$energy),
          p(strong("Mood: "),   info$mood),
          p(strong("Food: "),   info$food))
    }
    
    tagList(
      fluidRow(
        column(4,
               stat_box(fmt_range(fertile_days$DayOfMonth),
                        "Fertile window days"),
               stat_box(fmt_range(period_days$DayOfMonth),
                        "Menstrual days")),
        column(4,
               stat_box(fmt_range(high_drive$DayOfMonth),
                        "High sex drive days (\u2605)"),
               stat_box(fmt_range(medium_drive$DayOfMonth),
                        "Medium sex drive days (\u25CF)")),
        column(4,
               stat_box(paste0(round(max(df$FertilityProbability) * 100), "%"),
                        "Peak fertility score"),
               stat_box(paste0(sum(df$SexDrive == "High"), " H / ",
                               sum(df$SexDrive == "Medium"), " M / ",
                               sum(df$SexDrive == "Low"), " L"),
                        "Sex-drive mix this month"))
      ),
      h3("Phase guidance this month"),
      lapply(phases_present, make_card)
    )
  })
  
  # ===== Full fertility curve =====
  output$fert_curve <- renderPlotly({
    df <- cycle_df()
    
    p <- ggplot(df, aes(x = Date, y = FertilityProbability,
                        text = Tooltip, group = 1)) +
      geom_area(fill = "#ffe5ee", alpha = 0.55) +
      geom_line(color = "#d6336c", linewidth = 0.9) +
      geom_point(data = df %>% filter(Fertile),
                 color = "#d62828", size = 1.6) +
      scale_y_continuous(labels = percent_format(accuracy = 1),
                         limits = c(0, 1)) +
      labs(x = NULL, y = "Relative fertility probability",
           title = "Estimated fertility probability (all cycles)",
           subtitle = "Red dots = estimated fertile window") +
      theme_minimal(base_size = 13) +
      theme(plot.title = element_text(face = "bold"))
    
    ggplotly(p, tooltip = "text") %>% layout(hovermode = "x unified")
  })
  
  # ===== Insights tab =====
  output$insights_ui <- renderUI({
    df    <- cycle_df()
    today <- Sys.Date()
    
    today_row <- df %>% filter(Date == today)
    if (nrow(today_row) == 0) today_row <- df %>% slice(1)
    
    fmt <- function(d) {
      if (length(d) == 0 || all(is.na(d))) "---"
      else format(d[1], "%d %b %Y")
    }
    
    next_period  <- df %>% filter(Phase == "Menstrual", Date > today) %>%
      slice(1) %>% pull(Date)
    next_ovul    <- df %>% filter(Phase == "Ovulation", Date > today) %>%
      slice(1) %>% pull(Date)
    next_fertile <- df %>% filter(Fertile, Date >= today) %>%
      slice(1) %>% pull(Date)
    fertile_end  <- df %>% filter(Fertile, Date >= today) %>%
      slice(n()) %>% pull(Date)
    
    stat_box <- function(val, lbl) {
      div(class = "stat-box",
          div(class = "stat-val", val),
          div(class = "stat-lbl", lbl))
    }
    
    tagList(
      fluidRow(
        column(3, stat_box(today_row$CycleDay, "Cycle day today")),
        column(3, stat_box(paste0(round(today_row$FertilityProbability * 100), "%"),
                           "Fertility score")),
        column(3, stat_box(as.character(today_row$Phase), "Current phase")),
        column(3, stat_box(as.character(today_row$SexDrive), "Sex drive"))
      ),
      hr(),
      h3("Upcoming events"),
      tags$ul(
        tags$li(strong("Next period: "),         fmt(next_period)),
        tags$li(strong("Next ovulation: "),      fmt(next_ovul)),
        tags$li(strong("Next fertile window: "), fmt(next_fertile),
                " to ", fmt(fertile_end))
      ),
      hr(),
      h3("Phase encyclopedia"),
      fluidRow(
        lapply(names(phase_info), function(ph) {
          info <- phase_info[[ph]]
          column(6,
                 div(class = paste0("phase-card phase-", ph),
                     h4(paste0(info$emoji, " ", ph)),
                     p(strong("Energy: "),    info$energy),
                     p(strong("Mood: "),      info$mood),
                     p(strong("Nutrition: "), info$food)))
        })
      ),
      hr(),
      h3("Sex-drive distribution across the year"),
      plotlyOutput("drive_bar", height = "300px"),
      hr(),
      div(class = "alert alert-warning",
          strong("Reminder: "),
          "Ovulation dates are estimates. If you are avoiding pregnancy, ",
          "do not rely on calendar dates alone - use a primary contraceptive method.")
    )
  })
  
  output$drive_bar <- renderPlotly({
    df <- cycle_df() %>% count(SexDrive, .drop = FALSE)
    p <- ggplot(df, aes(x = SexDrive, y = n, fill = SexDrive)) +
      geom_col(width = 0.6) +
      scale_fill_manual(values = sexdrive_colors) +
      labs(x = NULL, y = "Number of days", fill = NULL) +
      theme_minimal(base_size = 12) +
      theme(legend.position = "none")
    ggplotly(p)
  })
  
  # ===== Data table =====
  output$data_tbl <- renderDT({
    df <- cycle_df() %>%
      mutate(Date     = format(Date, "%a, %d %b %Y"),
             Phase    = as.character(Phase),
             SexDrive = as.character(SexDrive)) %>%
      select(Date, CycleDay, Phase, Fertile,
             `Fertility %` = FertilityProbability,
             SexDrive, SexDriveSource, Energy, MonthYear)
    
    datatable(df,
              options = list(pageLength = 15, scrollX = TRUE, dom = "ftip"),
              rownames = FALSE,
              filter = "top") %>%
      formatStyle("Fertile", backgroundColor = styleEqual(TRUE, "#ffe0e6"))
  })
  
  # ===== CSV download =====
  output$download_csv <- downloadHandler(
    filename = function() paste0("cycle_plan_", Sys.Date(), ".csv"),
    content  = function(file) {
      out <- cycle_df() %>%
        transmute(
          Date                    = format(Date, "%d-%m-%Y"),
          CycleDay,
          Phase,
          Fertile,
          `Fertility Probability` = FertilityProbability,
          `Sex Drive`             = SexDrive,
          `Sex Drive Source`      = SexDriveSource,
          Energy
        )
      readr::write_csv(out, file)
    }
  )
}

shinyApp(ui, server)
